def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the color used for full horizontal and vertical divider lines.
    scores = {}
    for row in grid:
        if len(set(row)) == 1 and row[0] != 0:
            scores[row[0]] = scores.get(row[0], 0) + 1
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1 and col[0] != 0:
            scores[col[0]] = scores.get(col[0], 0) + 1
    if not scores:
        return [row[:] for row in grid]
    divider = max(scores, key=scores.get)

    divider_rows = [r for r in range(h) if all(v == divider for v in grid[r])]
    divider_cols = [c for c in range(w) if all(grid[r][c] == divider for r in range(h))]

    row_ranges = []
    start = 0
    for r in divider_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))

    col_ranges = []
    start = 0
    for c in divider_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    out = [row[:] for row in grid]
    nr, nc = len(row_ranges), len(col_ranges)

    def reflect(shape, height, width, flip_v, flip_h):
        return frozenset(
            (height - 1 - r if flip_v else r,
             width - 1 - c if flip_h else c)
            for r, c in shape
        )

    colors = {v for row in grid for v in row if v not in (0, divider)}

    for color in colors:
        shapes = [[set() for _ in range(nc)] for _ in range(nr)]
        for i, (r0, r1) in enumerate(row_ranges):
            for j, (c0, c1) in enumerate(col_ranges):
                for r in range(r0, r1):
                    for c in range(c0, c1):
                        if grid[r][c] == color:
                            shapes[i][j].add((r - r0, c - c0))

        for i in range(nr - 1):
            for j in range(nc - 1):
                block = [
                    shapes[i][j], shapes[i][j + 1],
                    shapes[i + 1][j], shapes[i + 1][j + 1]
                ]
                missing = [k for k, s in enumerate(block) if not s]
                if len(missing) != 1:
                    continue

                dims = [
                    (row_ranges[i][1] - row_ranges[i][0],
                     col_ranges[j][1] - col_ranges[j][0]),
                    (row_ranges[i][1] - row_ranges[i][0],
                     col_ranges[j + 1][1] - col_ranges[j + 1][0]),
                    (row_ranges[i + 1][1] - row_ranges[i + 1][0],
                     col_ranges[j][1] - col_ranges[j][0]),
                    (row_ranges[i + 1][1] - row_ranges[i + 1][0],
                     col_ranges[j + 1][1] - col_ranges[j + 1][0]),
                ]
                if len(set(dims)) != 1:
                    continue
                height, width = dims[0]

                positions = [(0, 0), (0, 1), (1, 0), (1, 1)]
                canonical = None
                for k, shape in enumerate(block):
                    if not shape:
                        continue
                    dr, dc = positions[k]
                    candidate = reflect(shape, height, width, bool(dr), bool(dc))
                    if all(
                        not block[q] or block[q] == reflect(
                            candidate, height, width,
                            bool(positions[q][0]), bool(positions[q][1])
                        )
                        for q in range(4)
                    ):
                        canonical = candidate
                        break

                if canonical is None:
                    continue

                k = missing[0]
                dr, dc = positions[k]
                fill = reflect(canonical, height, width, bool(dr), bool(dc))
                ri, cj = i + dr, j + dc
                r0, _ = row_ranges[ri]
                c0, _ = col_ranges[cj]
                for rr, cc in fill:
                    out[r0 + rr][c0 + cc] = color

    return out
